/// <summary>
/// METTelemetryDMFBatchLogging class extending methods of METTelemetryBase class
/// </summary>
final class METTelemetryDMFBatchLogging extends METTelemetryBase
{
    public Batch batch;
    public notes error;
}

Method.Source:
/// <summary>
/// constructor
/// </summary>
/// <param name = "_batch">_batch</param>
/// <param name = "_error">_error</param>
protected void new(Batch _batch, str _error)
{
    super();
    batch = _batch;
    this.error = _error;
    this.eventId = METApplicationInsightsEventIds::DMFBatchLogging;
}

/// <summary>
/// METTelemetryDMFBatchLogging
/// </summary>
/// <param name = "_batch">_batch</param>
/// <param name = "_error">_error</param>
/// <returns>METTelemetryDMFBatchLogging</returns>
public static METTelemetryDMFBatchLogging construct(Batch _batch, str _error)
{
    return new METTelemetryDMFBatchLogging(_batch,_error);
}

/// <summary>
/// shouldLogEvent
/// </summary>
/// <returns>boolean</returns>
protected boolean shouldLogEvent()
{
    if(!this.error && telemetryLoggingParams.SeverityLevel > METTelemetrySeverityLevel::Information)
    {
        return false;
    }
    return true;
}

/// <summary>
/// populateProperties
/// </summary>
protected void populateProperties()
{
    //todo change to constant
    this.addBaseProperty(METApplicationInsightsEventProperties::BatchJobId, strFmt('%1',batch.BatchJobId));
    this.addBaseProperty(METApplicationInsightsEventProperties::BatchJobTaskId, strFmt('%1',batch.RecId));
    this.addBaseProperty(METApplicationInsightsEventProperties::BatchJobName, batch.Caption);
    this.addBaseProperty(METApplicationInsightsEventProperties::StartDateTime, strFmt('%1',batch.StartDateTime));
    this.addBaseProperty(METApplicationInsightsEventProperties::LegalEntity, batch.Company);
    this.addBaseProperty(METApplicationInsightsEventProperties::ExceptionMessage, error);
    this.addBaseProperty(METApplicationInsightsEventProperties::CallStack, METSysGlobalTelemetry::formatXppCallStack(xSession::xppCallStack()));
}
